<template>
  <main class="auth-shell"><div class="auth-visual"><NuxtLink to="/" class="visual-logo">Trove</NuxtLink><div class="visual-copy"><span>Путешествия, которые хочется помнить</span><h2>Сохраняйте идеи.<br/>Возвращайтесь к ним.</h2><p>Избранное, бронирования и персональные предложения — в одном аккаунте.</p></div></div><section class="auth-panel"><div class="auth-card"><NuxtLink to="/" class="logo">Trove<span>.</span></NuxtLink><div class="mobile-kicker">Личный кабинет</div><h1>С возвращением</h1><p class="intro">Войдите, чтобы продолжить планировать путешествие.</p><form @submit.prevent="submit"><label>Почта или телефон<input v-model="identifier" autocomplete="username" required placeholder="you@example.com или +7 999..." /></label><label>Пароль<div class="password-field"><input v-model="password" type="password" autocomplete="current-password" required placeholder="Введите пароль" /><span>•••</span></div></label><p v-if="error" class="error">{{ error }}</p><button class="submit" :disabled="loading">{{ loading ? 'Входим…' : 'Войти' }}</button></form><div class="links"><NuxtLink to="/auth/forgot-password">Забыли пароль?</NuxtLink><NuxtLink to="/auth/register">Создать аккаунт <span>→</span></NuxtLink></div></div></section></main>
</template>
<script setup lang="ts">
import { useAuth } from '../../../composables/useAuth';

const identifier = ref(''); const password = ref(''); const loading = ref(false); const error = ref(''); const auth = useAuth()
const submit = async () => { loading.value=true; error.value=''; try { await auth.login(identifier.value,password.value); await navigateTo('/account') } catch (e:any) { error.value = e?.data?.error === 'RATE_LIMITED' ? 'Слишком много попыток. Попробуйте позже.' : 'Неверная почта/телефон или пароль.' } finally { loading.value=false } }
</script>

